SELECT *
FROM passenger_ai_message
WHERE conversation_id = #{conversationId}
  AND client_message_no = #{clientMessageNo}

SELECT *
FROM passenger_ai_message
WHERE conversation_id = #{conversationId}
  AND role = #{role}
ORDER BY sequence_no DESC
LIMIT 1

SELECT *
FROM passenger_ai_message
WHERE conversation_id = #{conversationId}
  AND request_no = #{requestNo}
  AND role = 'USER'

SELECT *
FROM passenger_ai_message
WHERE conversation_id = #{conversationId}
  AND request_no = #{requestNo}
  AND role = 'ASSISTANT'

SELECT *
FROM passenger_ai_message
WHERE conversation_id = #{conversationId}
  AND sequence_no < #{beforeSequence}
ORDER BY sequence_no DESC
LIMIT #{limit}
